insert into public.catalog_libraries(id,code,slug,steward_organization_id,status,created_by)values('f2040000-0000-4000-8000-000000000001','ACTIVATION204','activation204','b2040000-0000-4000-8000-000000000001','DRAFT','a2040000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values('c2040000-0000-4000-8000-000000000003','b2040000-0000-4000-8000-000000000001','a2040000-0000-4000-8000-000000000003','ACTIVE',now());
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values('c2040000-0000-4000-8000-000000000004','b2040000-0000-4000-8000-000000000001','a2040000-0000-4000-8000-000000000004','ACTIVE',now());
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values('c2040000-0000-4000-8000-000000000005','b2040000-0000-4000-8000-000000000001','a2040000-0000-4000-8000-000000000005','ACTIVE',now());
