create temporary table activation_results(kind text primary key,value jsonb);grant select,insert on activation_results to authenticated;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('PROPOSE1',public.propose_franchise_governance('f2040000-0000-4000-8000-000000000001','b2040000-0000-4000-8000-000000000001','FRANCHISEE','ACT204_1','Territoire 1','النطاق 1','{}',now()-interval'1 day',now()+interval'1 year',100000,'UPFRONT',0,'{"scope":"approved"}','{}','{}','activation204-3@example.invalid',repeat('1',64),'fr-MA','{}','Proposition approuvée 1','activation204-proposal-1'));
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select public.decide_franchise_governance((select(value->>'approval_request_id')::uuid from activation_results where kind='PROPOSE1'),'APPROVE','Approbation indépendante',1,'activation204-approval-1');
reset role;
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
reset role;
update public.organizations set status='PENDING' where id='b2040000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select public.accept_signed_franchise_invitation((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),'activation-status-blocked')$$,'42501','FRANCHISE_ACTIVATION_ORGANIZATION_NOT_ACTIVE','AAL2 with pending legal passport asks for organization activation, not another factor');
reset role;
select is((select status from public.franchises where id=(select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1')),'LIBRARY_ASSIGNED','failed contractual activation does not activate the franchise');
select is((select count(*)::integer from public.franchise_activation_evidence where invitation_id=(select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1')),0,'failed prerequisites create no activation evidence');
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
select throws_ok($$select public.accept_signed_franchise_invitation((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),'activation-factor-blocked')$$,'42501','FRANCHISE_ACTIVATION_MFA_REQUIRED','AAL1 still cannot perform contractual activation');
reset role;
update public.organizations set status='ACTIVE' where id='b2040000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select public.accept_signed_franchise_invitation((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'),repeat('1',64),1,(select(value->>'mandate_version_id')::uuid from activation_results where kind='PROPOSE1'),(public.franchise_invitation_activation_preview((select(value->>'invitation_id')::uuid from activation_results where kind='PROPOSE1'))->>'mandateHash'),'activation-proof-blocked')$$,'55000','FRANCHISE_SIGNED_MANDATE_REQUIRED','an active AAL2 passport still requires a real signed mandate');
reset role;
select*from finish();rollback;
